import{createRequire}from'node:module';import{readFileSync,writeFileSync,readdirSync,existsSync}from'node:fs';import{execFileSync}from'node:child_process';import{fileURLToPath}from'node:url';import{join,delimiter}from'node:path';import{createHash}from'node:crypto';
const require=createRequire(import.meta.url),{MC_VERSION:version}=require('../lib/mcassets.js'),root=fileURLToPath(new URL('../',import.meta.url)),cache=join(root,'cache/port-'+version),jars=p=>existsSync(p)?readdirSync(p,{withFileTypes:true}).flatMap(e=>e.isDirectory()?jars(join(p,e.name)):e.name.endsWith('.jar')?[join(p,e.name)]:[]):[];
const cp=[join(cache,'client.jar'),join(cache,'server.jar'),...jars(join(cache,'bundler/META-INF')),...jars(join(cache,'client-libraries'))].join(delimiter),out=join(cache,'bundle.json');execFileSync('java',['-cp',cp,join(root,'tools/ExtractBundle.java'),out,join(cache,'client.txt')],{cwd:cache,stdio:'inherit'});const data=JSON.parse(readFileSync(out));writeFileSync(join(root,'client/js/game/bundle-data.js'),'// Extracted native '+version+' bundle rules.\nexport const BUNDLE_NATIVE='+JSON.stringify({...data,weightCases:undefined})+';\n');writeFileSync(join(root,'tools/fixtures/bundle-native.json'),JSON.stringify({source:{version,clientJarSha1:createHash('sha1').update(readFileSync(join(cache,'client.jar'))).digest('hex')},...data})+'\n');
